tool_calls.arguments:
{"command":"kubectl patch deployment app -n restricted-app --patch '
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "securityContext": {
              "allowPrivilegeEscalation": false,
              "capabilities": {
                "drop": ["ALL"]
              },
              "seccompProfile": {
                "type": "RuntimeDefault"
              }
            }
          }
        ],
        "securityContext": {
          "runAsNonRoot": true
        }
      }
    }
  }
}'"}

